package com.bank.reporting.service;

import java.util.logging.Logger;

// Finds the length of the shortest subarray whose sorting sorts the whole array.
public class WindowSortAnalyzer {
    private static final Logger log = Logger.getLogger(WindowSortAnalyzer.class.getName());

    public int shortestWindowToSort(int[] balances) {
        if (balances == null || balances.length < 2) return 0;
        int n = balances.length;

        int left = 0;
        while (left < n - 1 && balances[left] <= balances[left + 1]) left++;
        if (left == n - 1) {
            log.info("Already sorted; window length 0.");
            return 0; // whole array is non-decreasing
        }

        int right = n - 1;
        while (right > 0 && balances[right] >= balances[right - 1]) right--;

        // Find min and max inside the candidate window [left, right].
        int windowMin = Integer.MAX_VALUE;
        int windowMax = Integer.MIN_VALUE;
        for (int k = left; k <= right; k++) {
            windowMin = Math.min(windowMin, balances[k]);
            windowMax = Math.max(windowMax, balances[k]);
        }

        // Extend left while any element is greater than windowMin.
        while (left > 0 && balances[left - 1] > windowMin) left--;
        // Extend right while any element is less than windowMax.
        while (right < n - 1 && balances[right + 1] < windowMax) right++;

        int length = right - left + 1;
        final int lenFinal = length;
        log.info(() -> "Shortest window to sort = " + lenFinal
                + " (indices " + 0 + " covered)");
        return length;
    }
}
