package com.bank.reporting;

import com.bank.reporting.service.WindowSortAnalyzer;
import java.util.Arrays;
import java.util.logging.Logger;

public class WindowSortDemo {
    private static final Logger log = Logger.getLogger(WindowSortDemo.class.getName());

    public static void main(String[] args) {
        // Tiered account balances that should be ascending but got shuffled.
        int[] balances = {1, 3, 2, 0, 5};
        log.info(() -> "Balances: " + Arrays.toString(balances));

        WindowSortAnalyzer analyzer = new WindowSortAnalyzer();
        int window = analyzer.shortestWindowToSort(balances);

        log.info(() -> "Minimal stretch to re-sort has length = " + window);
    }
}
